package com.carebridge.backend.integration;
import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.when;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.carebridge.backend.common.config.JpaAuditingConfig;import com.carebridge.backend.config.MockMvcSecurityBuilderConfig;import com.carebridge.backend.partner.controller.SponsoredCampaignController;import com.carebridge.backend.partner.dto.response.SubmitSponsoredContentResponse;import com.carebridge.backend.partner.entity.CampaignApprovalStatus;import com.carebridge.backend.partner.exception.PartnerException;import com.carebridge.backend.partner.service.SponsoredCampaignService;import com.carebridge.backend.security.config.SecurityConfig;import com.carebridge.backend.security.jwt.JwtTokenProvider;import com.carebridge.backend.security.repository.UserRepository;import java.time.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.*;import org.springframework.http.MediaType;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
@WebMvcTest(value=SponsoredCampaignController.class,excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes=JpaAuditingConfig.class)) @Import({SecurityConfig.class,MockMvcSecurityBuilderConfig.class}) class SubmitSponsoredContentIntegrationTest{
static final UUID OWNER=UUID.fromString("f5000000-0000-0000-0000-000000000001"),ORG=UUID.fromString("f6000000-0000-0000-0000-000000000001"),ID=UUID.fromString("f7000000-0000-0000-0000-000000000001");static final String BODY="{\"title\":\"Offer\",\"sponsorLabel\":\"Sponsored\"}";@Autowired MockMvc mvc;@MockitoBean SponsoredCampaignService service;@MockitoBean JwtTokenProvider jwt;@MockitoBean UserRepository users;
@Test @WithMockUser(username="f5000000-0000-0000-0000-000000000001",roles="PARTNER") void sscTcInt001_returnsPendingUnreviewed()throws Exception{when(service.submitCampaign(any(),eq(OWNER))).thenReturn(new SubmitSponsoredContentResponse(ID,ORG,"Offer",null,null,null,"Sponsored",CampaignApprovalStatus.PENDING,Instant.now()));mvc.perform(post("/api/v1/partner/campaigns").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isCreated()).andExpect(jsonPath("$.data.approvalStatus").value("PENDING"));}
@Test @WithMockUser(username="f5000000-0000-0000-0000-000000000001",roles="PARTNER") void sscTcInt002_nonApprovedReturns409()throws Exception{when(service.submitCampaign(any(),eq(OWNER))).thenThrow(PartnerException.campaignOrganizationNotApproved());mvc.perform(post("/api/v1/partner/campaigns").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isConflict()).andExpect(jsonPath("$.error").value("PTR-014"));}}
